constraints:
1 ≤ Number of nodes ≤ 10^{5}
1 ≤ Data of a node ≤ 10^{6}

expected time complexity: O(N).
expected auxiliary space: O(Height of the BST).

standard_solution_code:
class Solution:

	def check(self, root, result):
		if root == None:
			return ['n', 'n']
		(a1, b1) = self.check(root.left, result)
		(a2, b2) = self.check(root.right, result)
		if a1 == 'f' and b1 == 'f' or (a2 == 'f' and b2 == 'f'):
			return ['f', 'f']
		if a1 == 'n' and b1 == 'n' and (a2 == 'n') and (b2 == 'n'):
			a1 = root.data
			b1 = root.data
			a2 = root.data
			b2 = root.data
			result.append(root)
			return (a1, b2)
		elif a1 == 'n' and b1 == 'n':
			a1 = root.data
			b1 = root.data
			if a2 <= root.data:
				return ['f', 'f']
			else:
				result.append(root)
				return (a1, b2)
		elif a2 == 'n' and b2 == 'n':
			a2 = root.data
			b2 = root.data
			if b1 >= root.data:
				return ['f', 'f']
			else:
				result.append(root)
				return (a1, b2)
		elif a2 <= root.data or b1 >= root.data:
			return ['f', 'f']
		else:
			result.append(root)
			return (a1, b2)

	def cal_size(self, root):
		if root == None:
			return 0
		lh = self.cal_size(root.left)
		rh = self.cal_size(root.right)
		return lh + rh + 1

	def largestBst(self, root):
		result = []
		a = self.check(root, result)
		size = 0
		for i in result:
			temp = self.cal_size(i)
			if temp > size:
				size = temp
		return size
